use lg_core::Money;
use lg_tax::{region, Line, RoundingScope};
use lg_tax::calc::breakdown;

#[test]
fn disc_l17() {
    let r = region("CH").unwrap();
    let b = breakdown(&[Line::goods("g", Money::of(500, "CHF"))], r, RoundingScope::PerLine).unwrap();
    assert_eq!(b.tax.minor(), 41);
}
